#include "common/topology.hpp"
int main(int argc,char**argv){try{require(argc==3,"router config result");auto c=read_json(argv[1]);size_t d=c["dimension"];auto m=c["methods"][1];auto ids=read_raw<int32_t>(m["ids"].get<std::string>());auto w=read_raw<float>(m["W"].get<std::string>());require(w.size()==ids.size()*d,"shape");require(!fs::exists(m["graph"].get<std::string>()),"fresh graph");hnswlib::InnerProductSpace space(d);auto t=Clock::now();HNSW g(&space,ids.size(),16,200,20260828);for(size_t i=0;i<ids.size();++i)g.addPoint(w.data()+i*d,ids[i]);g.setEf(10);double s=seconds(t);g.saveIndex(m["graph"].get<std::string>());for(size_t i=0;i<ids.size();++i)require(g.getExternalLabel(i)==size_t(ids[i])&&!memcmp(g.getDataByInternalId(i),w.data()+i*d,d*4),"all labels/vectors");write_json(argv[2],{{"status","PASS"},{"H",ids.size()},{"build_seconds",s},{"all_label_vector_checks",ids.size()},{"graph_builds",1}});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
